/* ---------------- Auth Screens ---------------- */
function AuthGate({ onAuthed }) {
  const [mode, setMode] = useState("login"); // login | signup
  const [method, setMethod] = useState("email"); // email | phone
  const [step, setStep] = useState("form"); // form | otp
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [otp, setOtp] = useState("");
  const [sentOtp, setSentOtp] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [pendingUser, setPendingUser] = useState(null);

  const reset = () => {
    setStep("form"); setOtp(""); setSentOtp(""); setError(""); setPendingUser(null);
  };

  const switchMode = (m) => { setMode(m); reset(); };
  const switchMethod = (m) => { setMethod(m); reset(); };

  async function handleEmailSubmit() {
    setError("");
    if (!email.trim() || !password) { setError("Email aur password dono bharein"); return; }
    if (mode === "signup" && !name.trim()) { setError("Naam likhein"); return; }
    setBusy(true);
    try {
      const user = mode === "signup"
        ? await api.signupEmail(name.trim(), email.trim().toLowerCase(), password)
        : await api.loginEmail(email.trim().toLowerCase(), password);
      onAuthed(user);
    } catch (e) {
      setError(e.message || "Kuch galat hua, dobara try karein");
    } finally {
      setBusy(false);
    }
  }

  async function handlePhoneRequestOtp() {
    setError("");
    const cleaned = phone.replace(/\D/g, "");
    if (cleaned.length < 10) { setError("Sahi mobile number daalein"); return; }
    if (mode === "signup" && !name.trim()) { setError("Naam likhein"); return; }
    setBusy(true);
    try {
      const res = await api.requestOtp(cleaned, mode === "signup" ? name.trim() : undefined);
      setSentOtp(res.demo_code || ""); // backend returns this only in demo mode — remove once real SMS is wired up
      setPendingUser({ cleaned });
      setStep("otp");
    } catch (e) {
      setError(e.message || "Kuch galat hua, dobara try karein");
    } finally {
      setBusy(false);
    }
  }

  async function handleVerifyOtp() {
    setError("");
    setBusy(true);
    try {
      const { cleaned } = pendingUser;
      const user = await api.verifyOtp(cleaned, otp, mode === "signup" ? name.trim() : undefined);
      onAuthed(user);
    } catch (e) {
      setError(e.message || "OTP galat hai");
    } finally {
      setBusy(false);
    }
  }

  const inputStyle = {
    width: "100%", padding: "14px 16px", borderRadius: 14, border: "1.5px solid #E5E8F5",
    fontFamily: "Inter, sans-serif", fontSize: 14.5, color: COLORS.midnight,
    outline: "none", boxSizing: "border-box",
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", background: COLORS.white }}>
      <div style={{
        padding: "44px 24px 26px", background: `linear-gradient(135deg, ${COLORS.indigo}, ${COLORS.midnight})`,
      }}>
        <div style={{ width: 50, height: 50, borderRadius: 15, background: COLORS.orange, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "Poppins", fontWeight: 800, color: "#fff", fontSize: 21, marginBottom: 16 }}>K</div>
        <div style={{ fontFamily: "Poppins, sans-serif", fontWeight: 800, fontSize: 22, color: "#fff" }}>
          Kam<span style={{ color: COLORS.orange }}>X</span> mein {mode === "login" ? "login karein" : "account banayein"}
        </div>
        <div style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, color: "#B9C0F0", marginTop: 4 }}>
          Ek hi account — kaam karwayein ya kaam karein
        </div>
      </div>

      <div style={{ flex: 1, padding: "22px 22px 0", overflowY: "auto" }}>
        {/* mode toggle */}
        <div style={{ display: "flex", background: COLORS.mist, borderRadius: 14, padding: 4, marginBottom: 18 }}>
          {["login", "signup"].map((m) => (
            <button key={m} onClick={() => switchMode(m)} style={{
              flex: 1, padding: "10px 0", borderRadius: 11, border: "none", cursor: "pointer",
              background: mode === m ? COLORS.white : "transparent",
              boxShadow: mode === m ? "0 2px 8px rgba(20,20,60,0.08)" : "none",
              fontFamily: "Poppins, sans-serif", fontWeight: 700, fontSize: 13.5,
              color: mode === m ? COLORS.indigo : COLORS.textDim,
            }}>
              {m === "login" ? "Login" : "Sign Up"}
            </button>
          ))}
        </div>

        {/* method toggle */}
        <div style={{ display: "flex", gap: 10, marginBottom: 18 }}>
          {[{ k: "email", label: "Email", icon: Mail }, { k: "phone", label: "Mobile + OTP", icon: Phone }].map((opt) => {
            const Icon = opt.icon;
            const active = method === opt.k;
            return (
              <button key={opt.k} onClick={() => switchMethod(opt.k)} style={{
                flex: 1, display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
                padding: "11px 0", borderRadius: 12, cursor: "pointer",
                border: active ? `1.5px solid ${COLORS.indigo}` : "1.5px solid #E5E8F5",
                background: active ? "#EEF0FB" : "#fff",
              }}>
                <Icon size={15} color={active ? COLORS.indigo : COLORS.textDim} />
                <span style={{ fontFamily: "Inter, sans-serif", fontWeight: 600, fontSize: 12.5, color: active ? COLORS.indigo : COLORS.textDim }}>{opt.label}</span>
              </button>
            );
          })}
        </div>

        {step === "form" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {mode === "signup" && (
              <input placeholder="Aapka naam" value={name} onChange={(e) => setName(e.target.value)} style={inputStyle} />
            )}
            {method === "email" ? (
              <>
                <input placeholder="Email address" value={email} onChange={(e) => setEmail(e.target.value)} style={inputStyle} type="email" />
                <div style={{ position: "relative" }}>
                  <input
                    placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)}
                    style={{ ...inputStyle, paddingRight: 44 }} type={showPw ? "text" : "password"}
                  />
                  <button onClick={() => setShowPw((s) => !s)} style={{ position: "absolute", right: 12, top: 0, bottom: 0, background: "none", border: "none", cursor: "pointer", display: "flex", alignItems: "center" }}>
                    {showPw ? <EyeOff size={17} color={COLORS.textDim} /> : <Eye size={17} color={COLORS.textDim} />}
                  </button>
                </div>
              </>
            ) : (
              <input placeholder="Mobile number" value={phone} onChange={(e) => setPhone(e.target.value)} style={inputStyle} type="tel" />
            )}

            {error && <div style={{ color: COLORS.danger, fontFamily: "Inter, sans-serif", fontSize: 12.5 }}>{error}</div>}

            <button
              disabled={busy}
              onClick={method === "email" ? handleEmailSubmit : handlePhoneRequestOtp}
              style={{
                marginTop: 6, width: "100%", padding: "15px", borderRadius: 14, border: "none",
                background: COLORS.orange, color: "#fff", fontFamily: "Poppins, sans-serif",
                fontWeight: 700, fontSize: 15, cursor: "pointer", opacity: busy ? 0.6 : 1,
                boxShadow: "0 10px 24px rgba(255,107,53,0.3)",
              }}
            >
              {busy ? "Please wait..." : method === "email" ? (mode === "login" ? "Login" : "Account banayein") : "OTP bhejein"}
            </button>
          </div>
        )}

        {step === "otp" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
            <div style={{ background: "#EEF0FB", borderRadius: 14, padding: "14px 16px", fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.indigo, lineHeight: 1.6 }}>
              Demo mode: aapka OTP hai <strong style={{ fontSize: 16, letterSpacing: 2 }}>{sentOtp}</strong>
              <br />(Real SMS ke liye backend pe SMS provider connect karna hoga)
            </div>
            <input
              placeholder="6-digit OTP" value={otp} onChange={(e) => setOtp(e.target.value.replace(/\D/g, "").slice(0, 6))}
              style={{ ...inputStyle, textAlign: "center", fontSize: 22, letterSpacing: 8, fontFamily: "Poppins" }}
              maxLength={6} inputMode="numeric"
            />
            {error && <div style={{ color: COLORS.danger, fontFamily: "Inter, sans-serif", fontSize: 12.5 }}>{error}</div>}
            <button
              disabled={busy} onClick={handleVerifyOtp}
              style={{
                width: "100%", padding: "15px", borderRadius: 14, border: "none",
                background: COLORS.orange, color: "#fff", fontFamily: "Poppins, sans-serif",
                fontWeight: 700, fontSize: 15, cursor: "pointer", opacity: busy ? 0.6 : 1,
              }}
            >
              {busy ? "Verifying..." : "Verify & Continue"}
            </button>
            <button onClick={() => setStep("form")} style={{ background: "none", border: "none", color: COLORS.textDim, fontFamily: "Inter, sans-serif", fontSize: 12.5, cursor: "pointer" }}>
              ← Number change karein
            </button>
          </div>
        )}
      </div>

      <div style={{ padding: "16px 22px 26px", textAlign: "center" }}>
        <div style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.textDim }}>
          KamX AI Engine — Created by Sujit Kumar
        </div>
      </div>
    </div>
  );
}

