/* ---------------- Partner Dashboard ---------------- */
function PartnerDashboard({ t, lang, currentUser, onMenu, onToggleLang, onUpdateCommission, onBecomePartner }) {
  const [commission, setCommission] = useState(currentUser.partnerCommission || 15);
  const [saving, setSaving] = useState(false);
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);

  const isPartner = currentUser.isPartner;

  const loadJobs = useCallback(async () => {
    setLoading(true);
    try {
      const bookings = await api.partnerBookings();
      setJobs(bookings.slice(0, 25));
    } catch {
      setJobs([]);
    }
    setLoading(false);
  }, []);

  useEffect(() => { if (isPartner) loadJobs(); }, [isPartner, loadJobs]);

  async function saveCommission() {
    setSaving(true);
    await onUpdateCommission(commission);
    setSaving(false);
  }

  if (!isPartner) {
    return (
      <div style={{ display: "flex", flexDirection: "column", height: "100%", background: COLORS.mist }}>
        <TopBar onMenu={onMenu} lang={lang} onToggleLang={onToggleLang} title={lang === "hi" ? "पार्टनर बनें" : "Become a Partner"} partnerMode />
        <div style={{ flex: 1, padding: 22, overflowY: "auto" }}>
          <div style={{ background: "#fff", borderRadius: 18, padding: 22, textAlign: "center", marginBottom: 18 }}>
            <Briefcase size={32} color={COLORS.indigo} style={{ marginBottom: 10 }} />
            <div style={{ fontFamily: "Poppins, sans-serif", fontWeight: 700, fontSize: 16, color: COLORS.midnight, marginBottom: 6 }}>
              {lang === "hi" ? "रोज़ाना कमाई शुरू करें" : "Start earning daily"}
            </div>
            <div style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.textDim, lineHeight: 1.6 }}>
              {lang === "hi" ? "Apna commission % khud chunein (10-20%). Baki paisa seedha aapko milega." : "Choose your own commission % (10-20%). The rest goes straight to you."}
            </div>
          </div>

          <div style={{ background: "#fff", borderRadius: 18, padding: 20, marginBottom: 16 }}>
            <div style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.textDim, marginBottom: 10 }}>
              {lang === "hi" ? "Apna commission % chunein" : "Choose your commission %"}
            </div>
            <input
              type="range" min={10} max={20} value={commission}
              onChange={(e) => setCommission(Number(e.target.value))}
              style={{ width: "100%", accentColor: COLORS.orange }}
            />
            <div style={{ textAlign: "center", marginTop: 8, fontFamily: "Poppins, sans-serif", fontWeight: 800, fontSize: 26, color: COLORS.indigo }}>
              {commission}%
            </div>
          </div>

          <button onClick={() => onBecomePartner(commission)} style={{ width: "100%", padding: 16, borderRadius: 14, border: "none", background: COLORS.orange, color: "#fff", fontFamily: "Poppins", fontWeight: 700, fontSize: 15, cursor: "pointer" }}>
            {lang === "hi" ? "पार्टनर मोड शुरू करें" : "Activate Partner Mode"}
          </button>
        </div>
      </div>
    );
  }

  const myJobs = jobs; // demo: shows all platform bookings as available "incoming work" pool
  const totalEarnings = myJobs.reduce((sum, j) => sum + (j.workerAmt || 0), 0);
  const totalCommissionPaid = myJobs.reduce((sum, j) => sum + (j.commissionAmt || 0), 0);

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", background: COLORS.mist }}>
      <TopBar onMenu={onMenu} lang={lang} onToggleLang={onToggleLang} title={lang === "hi" ? "पार्टनर डैशबोर्ड" : "Partner Dashboard"} partnerMode />
      <div style={{ flex: 1, padding: 18, overflowY: "auto" }}>
        {/* earnings summary */}
        <div style={{ background: `linear-gradient(135deg, ${COLORS.midnight}, ${COLORS.indigo})`, borderRadius: 18, padding: 20, color: "#fff", marginBottom: 14 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
            <TrendingUp size={16} color={COLORS.green} />
            <span style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: "#B9C0F0" }}>{lang === "hi" ? "अनुमानित कमाई" : "Estimated earnings"}</span>
          </div>
          <div style={{ fontFamily: "Poppins, sans-serif", fontWeight: 800, fontSize: 28 }}>₹{totalEarnings}</div>
          <div style={{ fontFamily: "Inter, sans-serif", fontSize: 11.5, color: "#B9C0F0", marginTop: 4 }}>
            {lang === "hi" ? `KamX commission diya: ₹${totalCommissionPaid}` : `KamX commission paid: ₹${totalCommissionPaid}`}
          </div>
        </div>

        {/* commission setting */}
        <div style={{ background: "#fff", borderRadius: 16, padding: 18, marginBottom: 14 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
            <Percent size={16} color={COLORS.orange} />
            <span style={{ fontFamily: "Poppins, sans-serif", fontWeight: 700, fontSize: 13.5, color: COLORS.midnight }}>
              {lang === "hi" ? "आपका कमीशन" : "Your commission"}
            </span>
          </div>
          <input
            type="range" min={10} max={20} value={commission}
            onChange={(e) => setCommission(Number(e.target.value))}
            style={{ width: "100%", accentColor: COLORS.orange }}
          />
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 8 }}>
            <span style={{ fontFamily: "Poppins, sans-serif", fontWeight: 800, fontSize: 20, color: COLORS.indigo }}>{commission}%</span>
            {commission !== currentUser.partnerCommission && (
              <button onClick={saveCommission} disabled={saving} style={{ padding: "8px 16px", borderRadius: 10, border: "none", background: COLORS.indigo, color: "#fff", fontFamily: "Inter, sans-serif", fontWeight: 600, fontSize: 12.5, cursor: "pointer" }}>
                {saving ? "..." : (lang === "hi" ? "सेव करें" : "Save")}
              </button>
            )}
          </div>
        </div>

        {/* job list */}
        <div style={{ display: "flex", alignItems: "center", gap: 8, margin: "6px 2px 10px" }}>
          <ClipboardList size={16} color={COLORS.indigo} />
          <span style={{ fontFamily: "Poppins, sans-serif", fontWeight: 700, fontSize: 13.5, color: COLORS.midnight }}>
            {lang === "hi" ? "हाल की बुकिंग्स" : "Recent bookings"}
          </span>
          <button onClick={loadJobs} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", display: "flex" }}>
            <RefreshCw size={14} color={COLORS.textDim} />
          </button>
        </div>

        {loading ? (
          <div style={{ textAlign: "center", padding: 30, color: COLORS.textDim, fontFamily: "Inter, sans-serif", fontSize: 13 }}>
            {lang === "hi" ? "लोड हो रहा है..." : "Loading..."}
          </div>
        ) : myJobs.length === 0 ? (
          <div style={{ background: "#fff", borderRadius: 14, padding: 24, textAlign: "center", fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.textDim }}>
            {lang === "hi" ? "अभी कोई बुकिंग नहीं है" : "No bookings yet"}
          </div>
        ) : (
          myJobs.map((j) => {
            const service = SERVICES.find((s) => s.key === j.serviceKey);
            return (
              <div key={j.id} style={{ background: "#fff", borderRadius: 14, padding: "14px 16px", marginBottom: 10, display: "flex", alignItems: "center", gap: 12 }}>
                <div style={{ width: 36, height: 36, borderRadius: 10, background: `${COLORS.green}1A`, display: "flex", alignItems: "center", justifyContent: "center" }}>
                  <CheckCircle2 size={17} color={COLORS.green} />
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontFamily: "Inter, sans-serif", fontWeight: 600, fontSize: 13, color: COLORS.midnight }}>{service ? t[service.key] : j.serviceKey}</div>
                  <div style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.textDim }}>{j.customerName || `Customer #${(j.customerId || "").slice(-5)}`}</div>
                </div>
                <div style={{ textAlign: "right" }}>
                  <div style={{ fontFamily: "Poppins, sans-serif", fontWeight: 700, fontSize: 13, color: COLORS.green }}>+₹{j.workerAmt}</div>
                  <div style={{ fontFamily: "Inter, sans-serif", fontSize: 10.5, color: COLORS.textDim }}>{j.commissionPct}% {lang === "hi" ? "कट" : "cut"}</div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

/* ---------------- Sidebar Menu ---------------- */
function Sidebar({ open, onClose, t, lang, currentUser, onNavigate, onLogout }) {
  const items = [
    { key: "account", icon: User },
    { key: "premium", icon: Crown },
    { key: "wallet", icon: Wallet },
    { key: "settings", icon: Settings },
  ];
  return (
    <div style={{ position: "absolute", inset: 0, zIndex: 50, pointerEvents: open ? "auto" : "none" }}>
      <div onClick={onClose} style={{ position: "absolute", inset: 0, background: "rgba(10,12,40,0.45)", opacity: open ? 1 : 0, transition: "opacity .25s" }} />
      <div style={{
        position: "absolute", top: 0, bottom: 0, left: 0, width: "78%", maxWidth: 300,
        background: COLORS.white, transform: open ? "translateX(0)" : "translateX(-100%)",
        transition: "transform .28s cubic-bezier(.22,1,.36,1)", display: "flex", flexDirection: "column",
      }}>
        <div style={{ background: COLORS.indigo, padding: "26px 20px 20px", color: "#fff" }}>
          <button onClick={onClose} style={{ background: "rgba(255,255,255,0.12)", border: "none", borderRadius: 8, width: 30, height: 30, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", marginBottom: 14 }}>
            <X size={16} color="#fff" />
          </button>
          <div style={{ width: 46, height: 46, borderRadius: "50%", background: COLORS.orange, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "Poppins", fontWeight: 700, fontSize: 17, marginBottom: 10 }}>
            {(currentUser.name || "U")[0].toUpperCase()}
          </div>
          <div style={{ fontFamily: "Poppins, sans-serif", fontWeight: 700, fontSize: 15.5 }}>{currentUser.name}</div>
          <div style={{ fontFamily: "Inter, sans-serif", fontSize: 11.5, color: "#B9C0F0" }}>{currentUser.email || currentUser.phone}</div>
          {currentUser.isPartner && (
            <div style={{ marginTop: 8, display: "inline-flex", alignItems: "center", gap: 6, background: "rgba(255,255,255,0.15)", borderRadius: 8, padding: "4px 10px" }}>
              <Briefcase size={12} color={COLORS.orange} />
              <span style={{ fontFamily: "Inter, sans-serif", fontSize: 11, fontWeight: 600 }}>Partner · {currentUser.partnerCommission}%</span>
            </div>
          )}
        </div>

        <div style={{ flex: 1, padding: "10px 12px", overflowY: "auto" }}>
          {items.map((item) => {
            const Icon = item.icon;
            return (
              <button key={item.key} onClick={() => onNavigate(item.key)} style={{ width: "100%", display: "flex", alignItems: "center", gap: 14, padding: "13px 12px", border: "none", background: "transparent", borderRadius: 12, cursor: "pointer", textAlign: "left" }}>
                <Icon size={19} color={COLORS.indigo} />
                <span style={{ flex: 1, fontFamily: "Inter, sans-serif", fontWeight: 600, fontSize: 14, color: COLORS.midnight }}>{t.menu[item.key]}</span>
                <ChevronRight size={15} color={COLORS.textDim} />
              </button>
            );
          })}

          {/* role switch */}
          <button onClick={() => onNavigate("toggleRole")} style={{ width: "100%", display: "flex", alignItems: "center", gap: 14, padding: "13px 12px", border: "none", background: "transparent", borderRadius: 12, cursor: "pointer", textAlign: "left" }}>
            {currentUser.partnerModeActive ? <ToggleRight size={19} color={COLORS.green} /> : <ToggleLeft size={19} color={COLORS.indigo} />}
            <span style={{ flex: 1, fontFamily: "Inter, sans-serif", fontWeight: 600, fontSize: 14, color: COLORS.midnight }}>
              {currentUser.partnerModeActive ? t.menu.partnerOff : t.menu.partner}
            </span>
            <ChevronRight size={15} color={COLORS.textDim} />
          </button>

          <div style={{ height: 1, background: "#EEEFF7", margin: "10px 12px" }} />

          <button onClick={() => onNavigate("founder")} style={{ width: "100%", display: "flex", alignItems: "center", gap: 14, padding: "13px 12px", border: "none", background: "transparent", borderRadius: 12, cursor: "pointer", textAlign: "left" }}>
            <Brain size={19} color={COLORS.orange} />
            <span style={{ flex: 1, fontFamily: "Inter, sans-serif", fontWeight: 600, fontSize: 14, color: COLORS.midnight }}>{t.menu.founder}</span>
            <ChevronRight size={15} color={COLORS.textDim} />
          </button>

          <button onClick={onLogout} style={{ width: "100%", display: "flex", alignItems: "center", gap: 14, padding: "13px 12px", border: "none", background: "transparent", borderRadius: 12, cursor: "pointer", textAlign: "left" }}>
            <LogOut size={19} color={COLORS.danger} />
            <span style={{ flex: 1, fontFamily: "Inter, sans-serif", fontWeight: 600, fontSize: 14, color: COLORS.danger }}>{t.menu.logout}</span>
          </button>
        </div>

        <div style={{ padding: "14px 18px 20px", borderTop: "1px solid #EEEFF7" }}>
          <div style={{ fontFamily: "Inter, sans-serif", fontSize: 10.5, color: COLORS.textDim, textAlign: "center" }}>{t.version}</div>
        </div>
      </div>
    </div>
  );
}

